#include <memory_resource>
#include <vector>
#include <iostream>

int main() {
    char buffer[1024];                        // stack block: no heap traffic at all
    std::pmr::monotonic_buffer_resource arena{
        buffer, sizeof(buffer)};              // hands out chunks, frees nothing individually

    std::pmr::vector<double> prices(&arena);  // vector allocates from the arena
    for (int i = 0; i < 100; ++i)
        prices.push_back(100.0 + i * 0.25);

    std::cout << prices.size() << ' ' << prices.back() << '\n';
    // arena dies with main's scope: one step reclaims everything
}
// Prints: 100 124.75

#include <cstdint>
#include <cstddef>
#include <iostream>

struct alignas(64) PaddedSlot {   // force one object per cache line
    double v[8];                  // 64 bytes of payload
};

struct BadOrder  { char c; double d; std::int32_t i; };  // 1 +7pad +8 +4 = 20 -> 24
struct GoodOrder { double d; std::int32_t i; char c; };  // 8 +4 +1 +3pad = 16

int main() {
    std::cout << sizeof(PaddedSlot) << ' ' << alignof(PaddedSlot) << '\n';
    std::cout << sizeof(BadOrder) << ' ' << sizeof(GoodOrder) << '\n';
}
// Prints: 64 64
//         24 16

